(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-079"]={"sura":79,"name_ar":"النازعات","name_en":"An-Nazi'at","verses":46,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":46,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=14\" class=\"link\">79:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>ஸூரத்துந் நாஸிஆத்தின் தஃப்ஸீர் (அத்தியாயம் - 79). இது மக்காவில் அருளப்பட்டது.</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَٰنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>மறுமை நாள் நிகழும் என்பதற்கு ஐந்து பண்புகளின் மீது சத்தியம் செய்தல்</strong><br />\r\n<br />\r\nஇப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), மஸ்ரூக் (ரஹ்), ஸயீத் பின் ஜுபைர் (ரஹ்), அபூ ஸாலிஹ், அபுத் துஹா மற்றும் அஸ்ஸுத்தீ (ரஹ்) ஆகியோர் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَالنَّازِعَاتِ</span> <span class=\"quran-arabic-font text-success\">غَرْقًا﴿</span><br />\r\n<br />\r\n(மூழ்கிப் பிடுங்குபவர்கள் மீது சத்தியமாக.) \"இவர்கள் ஆதமின் சந்ததிகளிடமிருந்து உயிர்களைப் பறிக்கும் வானவர்கள் ஆவார்கள்.\" அந்த வானவர்களால் சிலருடைய உயிர்கள் மிகவும் சிரமத்துடன் பறிக்கப்படுகின்றன; அது அவர்கள் மூழ்கடிக்கப்படுவதைப் போன்ற வேதனையான நிலையில் இருக்கும். இன்னும் சிலருடைய உயிர்களை வானவர்கள் மிக எளிதாகவும் வேகமாகவும் பறிக்கின்றனர்; அவர்களின் வேகத்தினால் ஒரு முடிச்சை அவிழ்ப்பது போல (அவரிடமிருந்து அவரது உயிரை) மிக லாவகமாகப் பிரித்தெடுப்பார்கள். இதையே அல்லாஹ்வின் இந்த வசனம் குறிப்பிடுகிறது: <span class=\"quran-arabic-font text-success\">﴾وَالنَّاشِطَاتِ</span> <span class=\"quran-arabic-font text-success\">نَشْطًا﴿</span><br />\r\n<br />\r\n(சுறுசுறுப்பாகக் கழற்றுபவர்கள் மீது சத்தியமாக.) இதனை இப்னு அப்பாஸ் (ரழி) குறிப்பிட்டுள்ளார்கள். அல்லாஹ்வின் அடுத்த வசனத்தைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَالسَّابِحَاتِ</span> <span class=\"quran-arabic-font text-success\">سَبْحًا﴿</span><br />\r\n<br />\r\n(நீந்திச் செல்பவர்கள் மீதும் சத்தியமாக.) இப்னு மஸ்ஊத் (ரழி) அவர்கள், \"அவர்கள் வானவர்கள்\" என்று கூறினார்கள். இதே போன்ற கருத்துக்கள் அலீ (ரழி), முஜாஹித் (ரஹ்), ஸயீத் பின் ஜுபைர் (ரஹ்) மற்றும் அபூ ஸாலிஹ் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளன. அல்லாஹ்வின் இந்த வசனத்தைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾فَالسَّابِقَاتِ</span> <span class=\"quran-arabic-font text-success\">سَبْقًا﴿</span><br />\r\n<br />\r\n(முந்திச் செல்பவர்கள் மீதும் சத்தியமாக.) இது வானவர்களைக் குறிக்கிறது என்று அலீ (ரழி), மஸ்ரூக் (ரஹ்), முஜாஹித் (ரஹ்), அபூ ஸாலிஹ் மற்றும் அல்-ஹஸன் அல்-பஸரீ (ரஹ்) ஆகியோரிடமிருந்து அறிவிக்கப்பட்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَالْمُدَبِّرَاتِ</span> <span class=\"quran-arabic-font text-success\">أَمْرًا﴿</span><br />\r\n<br />\r\n(காரியங்களை நிர்வகிப்பவர்கள் மீதும் சத்தியமாக.) அலீ (ரழி), முஜாஹித் (ரஹ்), அதாஃ (ரஹ்), அபூ ஸாலிஹ், அல்-ஹஸன் (ரஹ்), கத்தாதா (ரஹ்), அர்-ரபீஃ பின் அனஸ் (ரஹ்) மற்றும் அஸ்-ஸுத்தீ (ரஹ்) ஆகியோர், \"அவர்கள் வானவர்கள்\" என்று கூறினார்கள். அல்-ஹஸன் (ரஹ்) அவர்கள் மேலும் கூறுகையில், \"அவர்கள் தங்கள் இறைவனாகிய வல்லமை மிக்கவனும், மகத்துவம் மிக்கவனுமாகிய அல்லாஹ்வின் கட்டளைப்படி, வானத்திலிருந்து பூமி வரையிலான விவகாரங்களை நிர்வகிக்கிறார்கள்\" என்று குறிப்பிட்டார்கள்.<br />\r\n<br />\r\n<strong>மறுமை நாளின் விளக்கம், மக்கள், மற்றும் அவர்கள் கூறுபவை</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَرْجُفُ</span> <span class=\"quran-arabic-font text-success\">الرَّاجِفَةُ</span> - <span class=\"quran-arabic-font text-success\">تَتْبَعُهَا</span> <span class=\"quran-arabic-font text-success\">الرَّادِفَةُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அர்-ராஜிஃபா நடுக்கமுறச் செய்யும் நாளில், அதனைத் தொடர்ந்து அர்-ராதிஃபா வரும்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இவை ஸூர் (எக்காளம்) ஊதப்படும் இரண்டு நிலைகளாகும் - முதலாவது மற்றும் இரண்டாவது.\" முஜாஹித் (ரஹ்), அல்-ஹஸன் (ரஹ்), கத்தாதா (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் பிறரும் இதே போன்றே கூறியுள்ளனர். முஜாஹித் (ரஹ்) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளதாவது: \"முதலாவது நிலையைப் பொறுத்தவரை, அது அல்லாஹ்வின் இந்த வசனமாகும்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَرْجُفُ</span> <span class=\"quran-arabic-font text-success\">الرَّاجِفَةُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அர்-ராஜிஃபா நடுக்கமுறச் செய்யும் நாளில்.) இது அல்லாஹ்வின் மற்றொரு வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَرْجُفُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَالْجِبَالُ﴿</span><br />\r\n<br />\r\n(பூமியும் மலைகளும் நடுங்கும் நாளில்.) (<a href=\"qurandisp.php?sura=73&ayah=14\" class=\"link\">73:14</a>). இரண்டாவது நிலை அர்-ராதிஃபா ஆகும். இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾وَحُمِلَتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَالْجِبَالُ</span> <span class=\"quran-arabic-font text-success\">فَدُكَّتَا</span> <span class=\"quran-arabic-font text-success\">دَكَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً﴿</span><br />\r\n<br />\r\n(பூமியும் மலைகளும் அவற்றின் இடங்களிலிருந்து பெயர்க்கப்பட்டு, ஒரே தூளாகத் தகர்க்கப்படும்.) (<a href=\"qurandisp.php?sura=69&ayah=14\" class=\"link\">69:14</a>)\" அல்லாஹ்வின் இந்த வசனத்தைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾قُلُوبٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَاجِفَةٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில் இதயங்கள் திடுக்கிட்டு நடுங்கும்.) \"இதன் பொருள் மக்கள் பயந்திருப்பார்கள் என்பதாகும்\" என்று இப்னு அப்பாஸ் (ரழி) கூறினார்கள். முஜாஹித் (ரஹ்) மற்றும் கத்தாதா (ரஹ்) ஆகியோரும் இதையே கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾أَبْصَارُهَا</span> <span class=\"quran-arabic-font text-success\">خَاشِعَةٌ﴿</span><br />\r\n<br />\r\n(அவர்களின் பார்வைகள் தாழ்ந்திருக்கும்.) அதாவது, மக்களின் கண்கள் தாழ்ந்திருக்கும். அவர்கள் காணும் அந்தப் பயங்கரமான காட்சிகளால் அவர்களின் கண்கள் சிறுமையுற்றும் இழிவடைந்தும் காணப்படும் என்று பொருள்படும். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">أَءِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَرْدُودُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْحَافِرَةِ﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறுகிறார்கள்: \"நிச்சயமாக நாங்கள் அல்-ஹாஃபிராவிற்கு மீண்டும் கொண்டுவரப்படுவோமா?\") அதாவது, குரைஷி இணைவைப்பாளர்களும் அவர்களைப் போலவே மறுமையை மறுப்பவர்களும் இவ்வாறு கூறுகின்றனர். அல்-ஹாஃபிராவில் - அதாவது கல்லறைகளில் - வைக்கப்பட்ட பிறகு மீண்டும் உயிர்ப்பிக்கப்படுவதை அவர்கள் சாத்தியமற்ற ஒன்றாகக் கருதுகின்றனர். இதனை முஜாஹித் (ரஹ்) அவர்கள் விளக்கியுள்ளார்கள். தங்கள் உடல்கள் அழிந்து, எலும்புகள் சிதைந்து மட்கிப் போன பிறகு, இது எப்படிச் சாத்தியம் என்று அவர்கள் எண்ணுகிறார்கள். எனவே அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَءِذَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">عِظَامًا</span> <span class=\"quran-arabic-font text-success\">نَّخِرَةً﴿</span><br />\r\n<br />\r\n(நாங்கள் மட்கிப்போன எலும்புகளாக ஆன பிறகும் கூடவா?) இது 'நாகிரஹ்' (<span class=\"quran-arabic-font text-success\">نَاخِرَةً</span>) என்றும் ஓதப்பட்டுள்ளது. இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரஹ்) மற்றும் கத்தாதா (ரஹ்) ஆகியோர், \"இதன் பொருள் உக்கிப்போன (மட்கிப்போன) என்பதாகும்\" என்றார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"எலும்பு மட்கிப்போய், அதனுள் காற்று புகும் நிலையில் இருப்பதே இதுவாகும்\" என்றார்கள். அவர்களின் கூற்றைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾تِلْكَ</span> <span class=\"quran-arabic-font text-success\">إِذًا</span> <span class=\"quran-arabic-font text-success\">كَرَّةٌ</span> <span class=\"quran-arabic-font text-success\">خَاسِرَةٌ﴿</span><br />\r\n<br />\r\n(அப்படியானால் அது நஷ்டமானதொரு திரும்புதலாகும்.) (<a href=\"qurandisp.php?sura=79&ayah=12\" class=\"link\">79:12</a>). முஹம்மத் பின் கஃப் (ரஹ்) அவர்கள் கூறினார்கள்: \"நாங்கள் இறந்த பிறகு அல்லாஹ் எங்களை மீண்டும் உயிர்ப்பித்தால், நிச்சயமாக நாங்கள் நஷ்டமடைந்தவர்களாக இருப்போம்\" என்று குரைஷிகள் கேலியாகக் கூறினர். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">زَجْرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span> * <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِالسَّاهِرَةِ﴿</span><br />\r\n<br />\r\n(ஆனால் அது ஒரே ஒரு அதட்டல் (சப்தம்) தான். இதோ, அவர்கள் அஸ்-ஸாஹிராவில் (வெட்டவெளியில்) இருப்பார்கள்.) அதாவது, இது அல்லாஹ்விடமிருந்து வரும் ஒரு கட்டளை. அது இரண்டாவது முறை நிகழாது; அதை உறுதிப்படுத்தவோ சரிபார்க்கவோ கால அவகாசமும் இருக்காது. மக்கள் அப்படியே நின்றபடி பார்த்துக் கொண்டிருப்பார்கள். உயிர்த்தெழுதலுக்காக ஸூர் எனும் எக்காளத்தை ஊதுமாறு வானவர் இஸ்ராஃபீல் (அலை) அவர்களுக்கு அல்லாஹ் கட்டளையிடும்போது இது நிகழும். அந்த நேரத்தில் ஆதி முதல் அந்தம் வரையிலான மக்கள் அனைவரும் தங்கள் இறைவனுக்கு முன்னால் நின்றபடி பார்த்துக் கொண்டிருப்பார்கள். இது குறித்து அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُوكُمْ</span> <span class=\"quran-arabic-font text-success\">فَتَسْتَجِيبُونَ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِهِ</span> <span class=\"quran-arabic-font text-success\">وَتَظُنُّونَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவன் உங்களை அழைக்கும் நாளில், அவனது புகழைப் பாடியவாறு அவனுக்குப் பணியாகப் பதிலளிப்பீர்கள்; மேலும் நீங்கள் மிகக் குறைந்த காலமே தங்கியிருந்ததாக எண்ணுவீர்கள்!) (<a href=\"qurandisp.php?sura=17&ayah=52\" class=\"link\">17:52</a>). அல்லாஹ் மேலும் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span> <span class=\"quran-arabic-font text-success\">كَلَمْحٍ</span> <span class=\"quran-arabic-font text-success\">بِالْبَصَرِ﴿</span><br />\r\n<br />\r\n(நமது கட்டளையானது கண் சிமிட்டும் நேரத்தைப் போன்ற ஒரே ஒரு முறைதான்.) (<a href=\"qurandisp.php?sura=54&ayah=50\" class=\"link\">54:50</a>). அல்லாஹ் மேலும் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَلَمْحِ</span> <span class=\"quran-arabic-font text-success\">الْبَصَرِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَقْرَبُ﴿</span><br />\r\n<br />\r\n(மறுமை நாளின் காரியமானது கண் சிமிட்டுவதைப் போன்றது அல்லது அதைவிட மிக நெருக்கமானது.) (<a href=\"qurandisp.php?sura=16&ayah=77\" class=\"link\">16:77</a>). பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِالسَّاهِرَةِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இதோ, அவர்கள் அஸ்-ஸாஹிராவில் இருப்பார்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அஸ்-ஸாஹிரா என்பது முழுப் பூமியைக் குறிக்கும்.\" ஸயீத் பின் ஜுபைர் (ரஹ்), கத்தாதா (ரஹ்) மற்றும் அபூ ஸாலிஹ் ஆகியோரும் இதனையே கூறியுள்ளனர். இக்ரிமா (ரஹ்), அல்-ஹஸன் (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் இப்னு ஸைத் (ரஹ்) ஆகியோர், \"அஸ்-ஸாஹிரா என்பது பூமியின் மேற்பரப்பு\" என்று கூறினர். முஜாஹித் (ரஹ்) அவர்கள் கூறுகையில், \"அவர்கள் பூமியின் கீழ்ப்பகுதியில் இருப்பார்கள், பின்னர் அவர்கள் அதன் மேற்பரப்பிற்கு கொண்டு வரப்படுவார்கள். அஸ்-ஸாஹிரா என்பது ஒரு சமமான இடமாகும்\" என்றார். அர்-ரபீஃ பின் அனஸ் (ரஹ்) அவர்கள் கூறுகையில்: <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِالسَّاهِرَةِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இதோ, அவர்கள் அஸ்-ஸாஹிராவில் இருப்பார்கள்.) \"அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُبَدَّلُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَالسَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">وَبَرَزُواْ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">الْوَاحِدِ</span> <span class=\"quran-arabic-font text-success\">الْقَهَّارِ﴿</span><br />\r\n<br />\r\n(பூமி வேறு பூமியாகவும், வானங்களும் மாற்றப்படும் அந்நாளில், அவர்கள் அடக்கியாளும் ஏகனாகிய அல்லாஹ்விடம் முன்னிலையாவார்கள்.) (<a href=\"qurandisp.php?sura=14&ayah=48\" class=\"link\">14:48</a>). மேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَيَسْأَلُونَكَ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالِ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span> <span class=\"quran-arabic-font text-success\">يَنسِفُهَا</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">نَسْفاً</span> - <span class=\"quran-arabic-font text-success\">فَيَذَرُهَا</span> <span class=\"quran-arabic-font text-success\">قَاعاً</span> <span class=\"quran-arabic-font text-success\">صَفْصَفاً</span> - <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">عِوَجاً</span> <span class=\"quran-arabic-font text-success\">وَلا</span> <span class=\"quran-arabic-font text-success\">أَمْتاً﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் உம்மிடம் மலைகளைப் பற்றிக் கேட்கிறார்கள்; நீர் கூறுவீராக: 'என் இறைவன் அவற்றை ஊதித் தவிடுபொடியாக்கி விடுவான். பின்னர் அதனை மேடுபள்ளமற்ற சமவெளியாக விட்டுவிடுவான். அதில் நீர் எந்தக் கோணலையோ மேட்டையோ காணமாட்டீர்.') (<a href=\"qurandisp.php?sura=20&ayah=105\" class=\"link\">20:105</a>-107). மேலும் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">نُسَيِّرُ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالَ</span> <span class=\"quran-arabic-font text-success\">وَتَرَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بَارِزَةً﴿</span><br />\r\n<br />\r\n(நாம் மலைகளை நகரச் செய்யும் நாளில், பூமியை ஒரு சமவெளியாக நீர் காண்பீர்.) (<a href=\"qurandisp.php?sura=18&ayah=47\" class=\"link\">18:47</a>). அப்போது வெண்மையான (வெள்ளியினாலான) புதிய பூமி கொண்டு வரப்படும்; அது இந்த உலகப் பூமியைப் போன்றது அல்ல. அந்தப் பூமியில் எந்தப் பாவமும் செய்யப்பட்டிருக்காது, எந்த இரத்தமும் சிந்தப்பட்டிருக்காது.\"<br />\r\n<br />","text":"ஸூரத்துந் நாஸிஆத்தின் தஃப்ஸீர் (அத்தியாயம் - 79). இது மக்காவில் அருளப்பட்டது.\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nமறுமை நாள் நிகழும் என்பதற்கு ஐந்து பண்புகளின் மீது சத்தியம் செய்தல்\n\r\n\n\r\nஇப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), மஸ்ரூக் (ரஹ்), ஸயீத் பின் ஜுபைர் (ரஹ்), அபூ ஸாலிஹ், அபுத் துஹா மற்றும் அஸ்ஸுத்தீ (ரஹ்) ஆகியோர் கூறினார்கள்: ﴾وَالنَّازِعَاتِ غَرْقًا﴿\n\r\n\n\r\n(மூழ்கிப் பிடுங்குபவர்கள் மீது சத்தியமாக.) \"இவர்கள் ஆதமின் சந்ததிகளிடமிருந்து உயிர்களைப் பறிக்கும் வானவர்கள் ஆவார்கள்.\" அந்த வானவர்களால் சிலருடைய உயிர்கள் மிகவும் சிரமத்துடன் பறிக்கப்படுகின்றன; அது அவர்கள் மூழ்கடிக்கப்படுவதைப் போன்ற வேதனையான நிலையில் இருக்கும். இன்னும் சிலருடைய உயிர்களை வானவர்கள் மிக எளிதாகவும் வேகமாகவும் பறிக்கின்றனர்; அவர்களின் வேகத்தினால் ஒரு முடிச்சை அவிழ்ப்பது போல (அவரிடமிருந்து அவரது உயிரை) மிக லாவகமாகப் பிரித்தெடுப்பார்கள். இதையே அல்லாஹ்வின் இந்த வசனம் குறிப்பிடுகிறது: ﴾وَالنَّاشِطَاتِ نَشْطًا﴿\n\r\n\n\r\n(சுறுசுறுப்பாகக் கழற்றுபவர்கள் மீது சத்தியமாக.) இதனை இப்னு அப்பாஸ் (ரழி) குறிப்பிட்டுள்ளார்கள். அல்லாஹ்வின் அடுத்த வசனத்தைப் பொறுத்தவரை: ﴾وَالسَّابِحَاتِ سَبْحًا﴿\n\r\n\n\r\n(நீந்திச் செல்பவர்கள் மீதும் சத்தியமாக.) இப்னு மஸ்ஊத் (ரழி) அவர்கள், \"அவர்கள் வானவர்கள்\" என்று கூறினார்கள். இதே போன்ற கருத்துக்கள் அலீ (ரழி), முஜாஹித் (ரஹ்), ஸயீத் பின் ஜுபைர் (ரஹ்) மற்றும் அபூ ஸாலிஹ் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளன. அல்லாஹ்வின் இந்த வசனத்தைப் பற்றி: ﴾فَالسَّابِقَاتِ سَبْقًا﴿\n\r\n\n\r\n(முந்திச் செல்பவர்கள் மீதும் சத்தியமாக.) இது வானவர்களைக் குறிக்கிறது என்று அலீ (ரழி), மஸ்ரூக் (ரஹ்), முஜாஹித் (ரஹ்), அபூ ஸாலிஹ் மற்றும் அல்-ஹஸன் அல்-பஸரீ (ரஹ்) ஆகியோரிடமிருந்து அறிவிக்கப்பட்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்: ﴾فَالْمُدَبِّرَاتِ أَمْرًا﴿\n\r\n\n\r\n(காரியங்களை நிர்வகிப்பவர்கள் மீதும் சத்தியமாக.) அலீ (ரழி), முஜாஹித் (ரஹ்), அதாஃ (ரஹ்), அபூ ஸாலிஹ், அல்-ஹஸன் (ரஹ்), கத்தாதா (ரஹ்), அர்-ரபீஃ பின் அனஸ் (ரஹ்) மற்றும் அஸ்-ஸுத்தீ (ரஹ்) ஆகியோர், \"அவர்கள் வானவர்கள்\" என்று கூறினார்கள். அல்-ஹஸன் (ரஹ்) அவர்கள் மேலும் கூறுகையில், \"அவர்கள் தங்கள் இறைவனாகிய வல்லமை மிக்கவனும், மகத்துவம் மிக்கவனுமாகிய அல்லாஹ்வின் கட்டளைப்படி, வானத்திலிருந்து பூமி வரையிலான விவகாரங்களை நிர்வகிக்கிறார்கள்\" என்று குறிப்பிட்டார்கள்.\n\r\n\n\r\nமறுமை நாளின் விளக்கம், மக்கள், மற்றும் அவர்கள் கூறுபவை\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்: ﴾يَوْمَ تَرْجُفُ الرَّاجِفَةُ - تَتْبَعُهَا الرَّادِفَةُ ﴿\n\r\n\n\r\n(அர்-ராஜிஃபா நடுக்கமுறச் செய்யும் நாளில், அதனைத் தொடர்ந்து அர்-ராதிஃபா வரும்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இவை ஸூர் (எக்காளம்) ஊதப்படும் இரண்டு நிலைகளாகும் - முதலாவது மற்றும் இரண்டாவது.\" முஜாஹித் (ரஹ்), அல்-ஹஸன் (ரஹ்), கத்தாதா (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் பிறரும் இதே போன்றே கூறியுள்ளனர். முஜாஹித் (ரஹ்) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளதாவது: \"முதலாவது நிலையைப் பொறுத்தவரை, அது அல்லாஹ்வின் இந்த வசனமாகும்: ﴾يَوْمَ تَرْجُفُ الرَّاجِفَةُ ﴿\n\r\n\n\r\n(அர்-ராஜிஃபா நடுக்கமுறச் செய்யும் நாளில்.) இது அல்லாஹ்வின் மற்றொரு வசனத்தைப் போன்றதாகும்: ﴾يَوْمَ تَرْجُفُ الْأَرْضُ وَالْجِبَالُ﴿\n\r\n\n\r\n(பூமியும் மலைகளும் நடுங்கும் நாளில்.) (73:14). இரண்டாவது நிலை அர்-ராதிஃபா ஆகும். இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றதாகும்: ﴾وَحُمِلَتِ الْأَرْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةً وَاحِدَةً﴿\n\r\n\n\r\n(பூமியும் மலைகளும் அவற்றின் இடங்களிலிருந்து பெயர்க்கப்பட்டு, ஒரே தூளாகத் தகர்க்கப்படும்.) (69:14)\" அல்லாஹ்வின் இந்த வசனத்தைப் பற்றி: ﴾قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ ﴿\n\r\n\n\r\n(அந்நாளில் இதயங்கள் திடுக்கிட்டு நடுங்கும்.) \"இதன் பொருள் மக்கள் பயந்திருப்பார்கள் என்பதாகும்\" என்று இப்னு அப்பாஸ் (ரழி) கூறினார்கள். முஜாஹித் (ரஹ்) மற்றும் கத்தாதா (ரஹ்) ஆகியோரும் இதையே கூறினார்கள். ﴾أَبْصَارُهَا خَاشِعَةٌ﴿\n\r\n\n\r\n(அவர்களின் பார்வைகள் தாழ்ந்திருக்கும்.) அதாவது, மக்களின் கண்கள் தாழ்ந்திருக்கும். அவர்கள் காணும் அந்தப் பயங்கரமான காட்சிகளால் அவர்களின் கண்கள் சிறுமையுற்றும் இழிவடைந்தும் காணப்படும் என்று பொருள்படும். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴿\n\r\n\n\r\n(அவர்கள் கூறுகிறார்கள்: \"நிச்சயமாக நாங்கள் அல்-ஹாஃபிராவிற்கு மீண்டும் கொண்டுவரப்படுவோமா?\") அதாவது, குரைஷி இணைவைப்பாளர்களும் அவர்களைப் போலவே மறுமையை மறுப்பவர்களும் இவ்வாறு கூறுகின்றனர். அல்-ஹாஃபிராவில் - அதாவது கல்லறைகளில் - வைக்கப்பட்ட பிறகு மீண்டும் உயிர்ப்பிக்கப்படுவதை அவர்கள் சாத்தியமற்ற ஒன்றாகக் கருதுகின்றனர். இதனை முஜாஹித் (ரஹ்) அவர்கள் விளக்கியுள்ளார்கள். தங்கள் உடல்கள் அழிந்து, எலும்புகள் சிதைந்து மட்கிப் போன பிறகு, இது எப்படிச் சாத்தியம் என்று அவர்கள் எண்ணுகிறார்கள். எனவே அல்லாஹ் கூறுகிறான்: ﴾أَءِذَا كُنَّا عِظَامًا نَّخِرَةً﴿\n\r\n\n\r\n(நாங்கள் மட்கிப்போன எலும்புகளாக ஆன பிறகும் கூடவா?) இது 'நாகிரஹ்' (نَاخِرَةً) என்றும் ஓதப்பட்டுள்ளது. இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரஹ்) மற்றும் கத்தாதா (ரஹ்) ஆகியோர், \"இதன் பொருள் உக்கிப்போன (மட்கிப்போன) என்பதாகும்\" என்றார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"எலும்பு மட்கிப்போய், அதனுள் காற்று புகும் நிலையில் இருப்பதே இதுவாகும்\" என்றார்கள். அவர்களின் கூற்றைப் பற்றி: ﴾تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ﴿\n\r\n\n\r\n(அப்படியானால் அது நஷ்டமானதொரு திரும்புதலாகும்.) (79:12). முஹம்மத் பின் கஃப் (ரஹ்) அவர்கள் கூறினார்கள்: \"நாங்கள் இறந்த பிறகு அல்லாஹ் எங்களை மீண்டும் உயிர்ப்பித்தால், நிச்சயமாக நாங்கள் நஷ்டமடைந்தவர்களாக இருப்போம்\" என்று குரைஷிகள் கேலியாகக் கூறினர். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ * فَإِذَا هُم بِالسَّاهِرَةِ﴿\n\r\n\n\r\n(ஆனால் அது ஒரே ஒரு அதட்டல் (சப்தம்) தான். இதோ, அவர்கள் அஸ்-ஸாஹிராவில் (வெட்டவெளியில்) இருப்பார்கள்.) அதாவது, இது அல்லாஹ்விடமிருந்து வரும் ஒரு கட்டளை. அது இரண்டாவது முறை நிகழாது; அதை உறுதிப்படுத்தவோ சரிபார்க்கவோ கால அவகாசமும் இருக்காது. மக்கள் அப்படியே நின்றபடி பார்த்துக் கொண்டிருப்பார்கள். உயிர்த்தெழுதலுக்காக ஸூர் எனும் எக்காளத்தை ஊதுமாறு வானவர் இஸ்ராஃபீல் (அலை) அவர்களுக்கு அல்லாஹ் கட்டளையிடும்போது இது நிகழும். அந்த நேரத்தில் ஆதி முதல் அந்தம் வரையிலான மக்கள் அனைவரும் தங்கள் இறைவனுக்கு முன்னால் நின்றபடி பார்த்துக் கொண்டிருப்பார்கள். இது குறித்து அல்லாஹ் கூறுகிறான்: ﴾يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلاَّ قَلِيلاً ﴿\n\r\n\n\r\n(அவன் உங்களை அழைக்கும் நாளில், அவனது புகழைப் பாடியவாறு அவனுக்குப் பணியாகப் பதிலளிப்பீர்கள்; மேலும் நீங்கள் மிகக் குறைந்த காலமே தங்கியிருந்ததாக எண்ணுவீர்கள்!) (17:52). அல்லாஹ் மேலும் கூறுகிறான்: ﴾وَمَا أَمْرُنَا إِلَّا وَاحِدَةٌ كَلَمْحٍ بِالْبَصَرِ﴿\n\r\n\n\r\n(நமது கட்டளையானது கண் சிமிட்டும் நேரத்தைப் போன்ற ஒரே ஒரு முறைதான்.) (54:50). அல்லாஹ் மேலும் கூறுகிறான்: ﴾وَمَآ أَمْرُ السَّاعَةِ إِلاَّ كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ﴿\n\r\n\n\r\n(மறுமை நாளின் காரியமானது கண் சிமிட்டுவதைப் போன்றது அல்லது அதைவிட மிக நெருக்கமானது.) (16:77). பின்னர் அல்லாஹ் கூறுகிறான்: ﴾فَإِذَا هُم بِالسَّاهِرَةِ ﴿\n\r\n\n\r\n(இதோ, அவர்கள் அஸ்-ஸாஹிராவில் இருப்பார்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அஸ்-ஸாஹிரா என்பது முழுப் பூமியைக் குறிக்கும்.\" ஸயீத் பின் ஜுபைர் (ரஹ்), கத்தாதா (ரஹ்) மற்றும் அபூ ஸாலிஹ் ஆகியோரும் இதனையே கூறியுள்ளனர். இக்ரிமா (ரஹ்), அல்-ஹஸன் (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் இப்னு ஸைத் (ரஹ்) ஆகியோர், \"அஸ்-ஸாஹிரா என்பது பூமியின் மேற்பரப்பு\" என்று கூறினர். முஜாஹித் (ரஹ்) அவர்கள் கூறுகையில், \"அவர்கள் பூமியின் கீழ்ப்பகுதியில் இருப்பார்கள், பின்னர் அவர்கள் அதன் மேற்பரப்பிற்கு கொண்டு வரப்படுவார்கள். அஸ்-ஸாஹிரா என்பது ஒரு சமமான இடமாகும்\" என்றார். அர்-ரபீஃ பின் அனஸ் (ரஹ்) அவர்கள் கூறுகையில்: ﴾فَإِذَا هُم بِالسَّاهِرَةِ ﴿\n\r\n\n\r\n(இதோ, அவர்கள் அஸ்-ஸாஹிராவில் இருப்பார்கள்.) \"அல்லாஹ் கூறுகிறான்: ﴾يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ وَبَرَزُواْ للَّهِ الْوَاحِدِ الْقَهَّارِ﴿\n\r\n\n\r\n(பூமி வேறு பூமியாகவும், வானங்களும் மாற்றப்படும் அந்நாளில், அவர்கள் அடக்கியாளும் ஏகனாகிய அல்லாஹ்விடம் முன்னிலையாவார்கள்.) (14:48). மேலும் அவன் கூறுகிறான்: ﴾وَيَسْأَلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفاً - فَيَذَرُهَا قَاعاً صَفْصَفاً - لاَّ تَرَى فِيهَا عِوَجاً وَلا أَمْتاً﴿\n\r\n\n\r\n(மேலும் அவர்கள் உம்மிடம் மலைகளைப் பற்றிக் கேட்கிறார்கள்; நீர் கூறுவீராக: 'என் இறைவன் அவற்றை ஊதித் தவிடுபொடியாக்கி விடுவான். பின்னர் அதனை மேடுபள்ளமற்ற சமவெளியாக விட்டுவிடுவான். அதில் நீர் எந்தக் கோணலையோ மேட்டையோ காணமாட்டீர்.') (20:105-107). மேலும் அல்லாஹ் கூறுகிறான்: ﴾وَيَوْمَ نُسَيِّرُ الْجِبَالَ وَتَرَى الْأَرْضَ بَارِزَةً﴿\n\r\n\n\r\n(நாம் மலைகளை நகரச் செய்யும் நாளில், பூமியை ஒரு சமவெளியாக நீர் காண்பீர்.) (18:47). அப்போது வெண்மையான (வெள்ளியினாலான) புதிய பூமி கொண்டு வரப்படும்; அது இந்த உலகப் பூமியைப் போன்றது அல்ல. அந்தப் பூமியில் எந்தப் பாவமும் செய்யப்பட்டிருக்காது, எந்த இரத்தமும் சிந்தப்பட்டிருக்காது.\""},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=26\" class=\"link\">79:26</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:26 ஐ பார்க்கவும்"},"26":{"html":"<strong>மூஸா (அலை) அவர்களின் வரலாற்றைக் குறிப்பிடுவதும், அல்லாஹ்வுக்கு அஞ்சுபவர்களுக்கு அதில் உள்ள படிப்பினையும்</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்கு, தனது தூதர் மூஸா (அலை) அவர்களைப் பற்றித் தெரிவிக்கின்றான். மூஸா (அலை) அவர்களை ஃபிர்அவ்னிடம் அனுப்பி, அத்தாட்சிகளைக் கொண்டு அவருக்கு உதவியதாக அவன் குறிப்பிடுகின்றான். இருப்பினும், ஃபிர்அவ்ன் தனது நிராகரிப்பிலும் அக்கிரமத்திலும் தொடர்ந்து ஈடுபட்டதால், அல்லாஹ் அவனை ஒரு வலிமையான மற்றும் மிகக் கடுமையான தண்டனையால் பிடிப்பதைக் காட்டினான். (முஹம்மது (ஸல்) அவர்களே!) உங்களுக்கு எதிராகச் செயல்படுபவர்களுக்கும், நீங்கள் எதனைக் கொண்டு அனுப்பப்பட்டீர்களோ அதை நிராகரிப்பவர்களுக்கும் இத்தகைய தண்டனையே கிடைக்கும். அதனால்தான் இந்த வரலாற்றின் இறுதியில் அல்லாஹ் கூறுகின்றான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَعِبْرَةً</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் அஞ்சுபவர்களுக்கு ஒரு படிப்பினை இருக்கிறது.) அல்லாஹ் இவ்வாறு கூறித் தொடங்குகின்றான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">أَتَاكَ</span> <span class=\"quran-arabic-font text-success\">حَدِيثُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(மூஸாவின் செய்தி உங்களுக்கு வந்ததா?) அதாவது, அவருடைய வரலாற்றைப் பற்றி நீங்கள் கேள்விப்பட்டிருக்கிறீர்களா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">نَادَاهُ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُ</span><br />\r\n<br />\r\n(அவருடைய இறைவன் அவரை அழைத்தபோது) அதாவது, அவனிடம் பேசி அவனை அழைத்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِالْوَادِ</span> <span class=\"quran-arabic-font text-success\">الْمُقَدَّسِ</span><br />\r\n<br />\r\n(புனிதமான பள்ளத்தாக்கில்) அதாவது தூய்மைப்படுத்தப்பட்ட இடத்தில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">طُوًى</span><br />\r\n<br />\r\n(துவா) சரியான கருத்தின்படி, இது ஒரு பள்ளத்தாக்கின் பெயராகும்; இது ஸூரா தா-ஹாவில் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது. அல்லாஹ் அவரிடம் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اذْهَبْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">طَغَى</span><br />\r\n<br />\r\n(ஃபிர்அவ்னிடம் செல்வீராக! நிச்சயமாக அவன் வரம்பு மீறிவிட்டான்.) அதாவது, அவன் பெருமையடிப்பவனாகவும், கலகக்காரனாகவும், ஆணவம் கொண்டவனாகவும் மாறிவிட்டான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقُلْ</span> <span class=\"quran-arabic-font text-success\">هَل</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span><br />\r\n<br />\r\n(மேலும் அவனிடம் கூறுவீராக: \"நீர் உன்னைப் பரிசுத்தமாக்கிக் கொள்ளத் தயாராக இருக்கின்றாயா?\") அதாவது, \"உன்னைப் பரிசுத்தப்படுத்தும் நேர்வழியை ஏற்றுக்கொள்வாயா?\" என்று அவனிடம் கேட்பதாகும். இதன் பொருள், 'நீ (இஸ்லாத்தை ஏற்று) கீழ்ப்படிந்து நடப்பாயா?' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَهْدِيَكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span><br />\r\n<br />\r\n(மேலும் உனது இறைவனின் பக்கம் நான் உனக்கு வழிகாட்டவா?) அதாவது, 'உனது இறைவனை வணங்குவதற்கு நான் உனக்கு வழிகாட்டுவேன்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَخْشَى</span><br />\r\n<br />\r\n(அதனால் நீர் அஞ்சுவீர்) அதாவது, 'உனது இதயம் கடினமாகவும், தீயதாகவும், நன்மையை விட்டும் வெகு தொலைவிலும் இருந்த பிறகு, அது அல்லாஹ்வுக்குப் பணிவுள்ளதாகவும், கீழ்ப்படிதலுள்ளதாகவும் மாறும்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَرَاهُ</span> <span class=\"quran-arabic-font text-success\">الْآيَةَ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span><br />\r\n<br />\r\n(பிறகு அவர் அவனுக்கு மாபெரும் அத்தாட்சியைக் காட்டினார்கள்.) இதன் பொருள், மூஸா (அலை) அவர்கள் தமது இந்த உண்மையான அழைப்புடன், அல்லாஹ்விடமிருந்து தாம் கொண்டு வந்தவற்றின் உண்மைத்தன்மைக்கு ஒரு வலிமையான ஆதாரத்தையும் தெளிவான சான்றையும் அவனுக்குக் காட்டினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَذَّبَ</span> <span class=\"quran-arabic-font text-success\">وَعَصَى</span><br />\r\n<br />\r\n(ஆனால் அவன் அதைப் பொய்ப்பித்ததோடு, மாறு செய்தான்.) அதாவது, அவன் (ஃபிர்அவ்ன்) உண்மையை நிராகரித்து, கீழ்ப்படிந்து நடக்குமாறு மூஸா (அலை) அவர்கள் இட்ட கட்டளையை எதிர்த்தான். அவனது இதயம் நிராகரிப்பிலேயே இருந்தது; மூஸா (அலை) அவர்களின் அழைப்பு அவனது உள்ளத்தையோ அல்லது வெளிப்படையான செயலையோ எவ்விதத்திலும் பாதிக்கவில்லை. மூஸா (அலை) அவர்கள் கொண்டு வந்தது உண்மைதான் என்பதை அவன் அறிந்திருந்த போதிலும், அவன் நம்பிக்கை கொள்ளவில்லை. ஏனெனில், அறிதல் என்பது உள்ளத்தின் அறிவாகும்; ஆனால் ஈமான் (நம்பிக்கை) என்பது உள்ளத்தின் செயலும், அந்த உண்மைக்குக் கட்டுப்பட்டுப் பணியுவதும் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَدْبَرَ</span> <span class=\"quran-arabic-font text-success\">يَسْعَى</span><br />\r\n<br />\r\n(பிறகு அவன் புறமுதுகு காட்டி, (உண்மையை எதிர்க்க) முயற்சித்தான்.) அதாவது, சத்தியத்திற்கு எதிராகப் பொய்யைக் கொண்டு பதிலளிப்பதற்காக முயன்றான். மூஸா (அலை) அவர்கள் காட்டிய அற்புதமான அத்தாட்சிகளை எதிர்கொள்வதற்காகச் சூனியக்காரர்களைத் திரட்டியது இதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَحَشَرَ</span> <span class=\"quran-arabic-font text-success\">فَنَادَى</span><br />\r\n<br />\r\n(எனவே அவன் (தன் மக்களை) ஒன்று திரட்டி, உரக்கக் கூறினான்.) அதாவது, தன் மக்கள் மத்தியில் இந்த அழைப்பை விடுத்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n<br />\r\n(கூறினான்: \"நானே உங்கள் மிக உயர்ந்த இறைவன்.\") இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் (ரழி) ஆகிய இருவரும் கூறினார்கள்: \"ஃபிர்அவ்ன்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٍ</span> <span class=\"quran-arabic-font text-success\">غَيْرِى</span><br />\r\n<br />\r\n('உங்களுக்கு என்னைத் தவிர வேறு எந்தக் கடவுளும் இருப்பதாக நான் அறியவில்லை') என்று கூறி நாற்பது வருடங்கள் சென்ற பிறகு சொன்ன வார்த்தையே இதுவாகும்.\" பிறகு அல்லாஹ் கூறுகின்றான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَخَذَهُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">نَكَالَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">وَالْأُولَى</span><br />\r\n<br />\r\n(எனவே அல்லாஹ் அவனை மறுமைக்கும் இம்மைக்குமான தண்டனையால் பிடித்தான்.) அதாவது, அல்லாஹ் அவனிடம் மிகக் கடுமையான முறையில் பழிவாங்கினான். இவ்வுலகில் அவனைப் போன்ற அக்கிரமக்காரர்களுக்கு அவனை ஒரு உதாரணமாகவும் எச்சரிக்கையாகவும் ஆக்கினான். இது அல்லாஹ் கூறுவது போல் உள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">بِئْسَ</span> <span class=\"quran-arabic-font text-success\">الرِّفْدُ</span> <span class=\"quran-arabic-font text-success\">الْمَرْفُودُ</span><br />\r\n<br />\r\n(மேலும் மறுமை நாளில் அவர்கள் பின்தொடரச் செய்யப்பட்ட இந்தப் பரிசு (சாபம்) மிகக் கெட்டதாகும்.) (<a href=\"qurandisp.php?sura=11&ayah=99\" class=\"link\">11:99</a>) அதாவது, இவ்வுலகில் ஒரு சாபம், அதைத் தொடர்ந்து மற்றொன்று, பிறகு மறுமையிலும் சாபம். இது அல்லாஹ் கூறுவது போல் உள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَئِمَّةً</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ</span><br />\r\n<br />\r\n(மக்களையும் நரகத்தின் பக்கம் அழைக்கும் தலைவர்களாக நாம் அவர்களை ஆக்கினோம்; மறுமை நாளில் அவர்கள் உதவி செய்யப்பட மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=28&ayah=41\" class=\"link\">28:41</a>). அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَعِبْرَةً</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் அஞ்சுபவர்களுக்கு ஒரு படிப்பினை இருக்கிறது.)<br />\r\n<br />","text":"மூஸா (அலை) அவர்களின் வரலாற்றைக் குறிப்பிடுவதும், அல்லாஹ்வுக்கு அஞ்சுபவர்களுக்கு அதில் உள்ள படிப்பினையும்\n\r\n\n\r\nஅல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்கு, தனது தூதர் மூஸா (அலை) அவர்களைப் பற்றித் தெரிவிக்கின்றான். மூஸா (அலை) அவர்களை ஃபிர்அவ்னிடம் அனுப்பி, அத்தாட்சிகளைக் கொண்டு அவருக்கு உதவியதாக அவன் குறிப்பிடுகின்றான். இருப்பினும், ஃபிர்அவ்ன் தனது நிராகரிப்பிலும் அக்கிரமத்திலும் தொடர்ந்து ஈடுபட்டதால், அல்லாஹ் அவனை ஒரு வலிமையான மற்றும் மிகக் கடுமையான தண்டனையால் பிடிப்பதைக் காட்டினான். (முஹம்மது (ஸல்) அவர்களே!) உங்களுக்கு எதிராகச் செயல்படுபவர்களுக்கும், நீங்கள் எதனைக் கொண்டு அனுப்பப்பட்டீர்களோ அதை நிராகரிப்பவர்களுக்கும் இத்தகைய தண்டனையே கிடைக்கும். அதனால்தான் இந்த வரலாற்றின் இறுதியில் அல்லாஹ் கூறுகின்றான்:\n\r\n\n\r\nإِنَّ فِى ذَلِكَ لَعِبْرَةً لِّمَن يَخْشَى\n\r\n\n\r\n(நிச்சயமாக இதில் அஞ்சுபவர்களுக்கு ஒரு படிப்பினை இருக்கிறது.) அல்லாஹ் இவ்வாறு கூறித் தொடங்குகின்றான்:\n\r\n\n\r\nهَلْ أَتَاكَ حَدِيثُ مُوسَى\n\r\n\n\r\n(மூஸாவின் செய்தி உங்களுக்கு வந்ததா?) அதாவது, அவருடைய வரலாற்றைப் பற்றி நீங்கள் கேள்விப்பட்டிருக்கிறீர்களா?\n\r\n\n\r\nإِذْ نَادَاهُ رَبُّهُ\n\r\n\n\r\n(அவருடைய இறைவன் அவரை அழைத்தபோது) அதாவது, அவனிடம் பேசி அவனை அழைத்தான்.\n\r\n\n\r\nبِالْوَادِ الْمُقَدَّسِ\n\r\n\n\r\n(புனிதமான பள்ளத்தாக்கில்) அதாவது தூய்மைப்படுத்தப்பட்ட இடத்தில்.\n\r\n\n\r\nطُوًى\n\r\n\n\r\n(துவா) சரியான கருத்தின்படி, இது ஒரு பள்ளத்தாக்கின் பெயராகும்; இது ஸூரா தா-ஹாவில் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது. அல்லாஹ் அவரிடம் கூறினான்:\n\r\n\n\r\nاذْهَبْ إِلَى فِرْعَوْنَ إِنَّهُ طَغَى\n\r\n\n\r\n(ஃபிர்அவ்னிடம் செல்வீராக! நிச்சயமாக அவன் வரம்பு மீறிவிட்டான்.) அதாவது, அவன் பெருமையடிப்பவனாகவும், கலகக்காரனாகவும், ஆணவம் கொண்டவனாகவும் மாறிவிட்டான்.\n\r\n\n\r\nفَقُلْ هَل لَّكَ إِلَى أَن تَزَكَّى\n\r\n\n\r\n(மேலும் அவனிடம் கூறுவீராக: \"நீர் உன்னைப் பரிசுத்தமாக்கிக் கொள்ளத் தயாராக இருக்கின்றாயா?\") அதாவது, \"உன்னைப் பரிசுத்தப்படுத்தும் நேர்வழியை ஏற்றுக்கொள்வாயா?\" என்று அவனிடம் கேட்பதாகும். இதன் பொருள், 'நீ (இஸ்லாத்தை ஏற்று) கீழ்ப்படிந்து நடப்பாயா?' என்பதாகும்.\n\r\n\n\r\nوَأَهْدِيَكَ إِلَى رَبِّكَ\n\r\n\n\r\n(மேலும் உனது இறைவனின் பக்கம் நான் உனக்கு வழிகாட்டவா?) அதாவது, 'உனது இறைவனை வணங்குவதற்கு நான் உனக்கு வழிகாட்டுவேன்.'\n\r\n\n\r\nفَتَخْشَى\n\r\n\n\r\n(அதனால் நீர் அஞ்சுவீர்) அதாவது, 'உனது இதயம் கடினமாகவும், தீயதாகவும், நன்மையை விட்டும் வெகு தொலைவிலும் இருந்த பிறகு, அது அல்லாஹ்வுக்குப் பணிவுள்ளதாகவும், கீழ்ப்படிதலுள்ளதாகவும் மாறும்.'\n\r\n\n\r\nفَأَرَاهُ الْآيَةَ الْكُبْرَى\n\r\n\n\r\n(பிறகு அவர் அவனுக்கு மாபெரும் அத்தாட்சியைக் காட்டினார்கள்.) இதன் பொருள், மூஸா (அலை) அவர்கள் தமது இந்த உண்மையான அழைப்புடன், அல்லாஹ்விடமிருந்து தாம் கொண்டு வந்தவற்றின் உண்மைத்தன்மைக்கு ஒரு வலிமையான ஆதாரத்தையும் தெளிவான சான்றையும் அவனுக்குக் காட்டினார்கள்.\n\r\n\n\r\nفَكَذَّبَ وَعَصَى\n\r\n\n\r\n(ஆனால் அவன் அதைப் பொய்ப்பித்ததோடு, மாறு செய்தான்.) அதாவது, அவன் (ஃபிர்அவ்ன்) உண்மையை நிராகரித்து, கீழ்ப்படிந்து நடக்குமாறு மூஸா (அலை) அவர்கள் இட்ட கட்டளையை எதிர்த்தான். அவனது இதயம் நிராகரிப்பிலேயே இருந்தது; மூஸா (அலை) அவர்களின் அழைப்பு அவனது உள்ளத்தையோ அல்லது வெளிப்படையான செயலையோ எவ்விதத்திலும் பாதிக்கவில்லை. மூஸா (அலை) அவர்கள் கொண்டு வந்தது உண்மைதான் என்பதை அவன் அறிந்திருந்த போதிலும், அவன் நம்பிக்கை கொள்ளவில்லை. ஏனெனில், அறிதல் என்பது உள்ளத்தின் அறிவாகும்; ஆனால் ஈமான் (நம்பிக்கை) என்பது உள்ளத்தின் செயலும், அந்த உண்மைக்குக் கட்டுப்பட்டுப் பணியுவதும் ஆகும்.\n\r\n\n\r\nثُمَّ أَدْبَرَ يَسْعَى\n\r\n\n\r\n(பிறகு அவன் புறமுதுகு காட்டி, (உண்மையை எதிர்க்க) முயற்சித்தான்.) அதாவது, சத்தியத்திற்கு எதிராகப் பொய்யைக் கொண்டு பதிலளிப்பதற்காக முயன்றான். மூஸா (அலை) அவர்கள் காட்டிய அற்புதமான அத்தாட்சிகளை எதிர்கொள்வதற்காகச் சூனியக்காரர்களைத் திரட்டியது இதைக் குறிக்கும்.\n\r\n\n\r\nفَحَشَرَ فَنَادَى\n\r\n\n\r\n(எனவே அவன் (தன் மக்களை) ஒன்று திரட்டி, உரக்கக் கூறினான்.) அதாவது, தன் மக்கள் மத்தியில் இந்த அழைப்பை விடுத்தான்.\n\r\n\n\r\nفَقَالَ أَنَاْ رَبُّكُمُ الْأَعْلَى\n\r\n\n\r\n(கூறினான்: \"நானே உங்கள் மிக உயர்ந்த இறைவன்.\") இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் (ரழி) ஆகிய இருவரும் கூறினார்கள்: \"ஃபிர்அவ்ன்,\n\r\n\n\r\nمَا عَلِمْتُ لَكُمْ مِّنْ إِلَـهٍ غَيْرِى\n\r\n\n\r\n('உங்களுக்கு என்னைத் தவிர வேறு எந்தக் கடவுளும் இருப்பதாக நான் அறியவில்லை') என்று கூறி நாற்பது வருடங்கள் சென்ற பிறகு சொன்ன வார்த்தையே இதுவாகும்.\" பிறகு அல்லாஹ் கூறுகின்றான்:\n\r\n\n\r\nفَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَى\n\r\n\n\r\n(எனவே அல்லாஹ் அவனை மறுமைக்கும் இம்மைக்குமான தண்டனையால் பிடித்தான்.) அதாவது, அல்லாஹ் அவனிடம் மிகக் கடுமையான முறையில் பழிவாங்கினான். இவ்வுலகில் அவனைப் போன்ற அக்கிரமக்காரர்களுக்கு அவனை ஒரு உதாரணமாகவும் எச்சரிக்கையாகவும் ஆக்கினான். இது அல்லாஹ் கூறுவது போல் உள்ளது:\n\r\n\n\r\nوَيَوْمَ الْقِيَامَةِ بِئْسَ الرِّفْدُ الْمَرْفُودُ\n\r\n\n\r\n(மேலும் மறுமை நாளில் அவர்கள் பின்தொடரச் செய்யப்பட்ட இந்தப் பரிசு (சாபம்) மிகக் கெட்டதாகும்.) (11:99) அதாவது, இவ்வுலகில் ஒரு சாபம், அதைத் தொடர்ந்து மற்றொன்று, பிறகு மறுமையிலும் சாபம். இது அல்லாஹ் கூறுவது போல் உள்ளது:\n\r\n\n\r\nوَجَعَلْنَاهُمْ أَئِمَّةً يَدْعُونَ إِلَى النَّارِ وَيَوْمَ الْقِيَامَةِ لاَ يُنصَرُونَ\n\r\n\n\r\n(மக்களையும் நரகத்தின் பக்கம் அழைக்கும் தலைவர்களாக நாம் அவர்களை ஆக்கினோம்; மறுமை நாளில் அவர்கள் உதவி செய்யப்பட மாட்டார்கள்.) (28:41). அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِنَّ فِى ذَلِكَ لَعِبْرَةً لِّمَن يَخْشَى\n\r\n\n\r\n(நிச்சயமாக இதில் அஞ்சுபவர்களுக்கு ஒரு படிப்பினை இருக்கிறது.)"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=33\" class=\"link\">79:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:33 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=33\" class=\"link\">79:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:33 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=33\" class=\"link\">79:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:33 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=33\" class=\"link\">79:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:33 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=33\" class=\"link\">79:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:33 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=33\" class=\"link\">79:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:33 ஐ பார்க்கவும்"},"33":{"html":"<strong>படைப்பை மீண்டும் உருவாக்குவதை விட வானங்களையும் பூமியையும் படைப்பது மிகவும் கடினமானது</strong><br />\r\n<br />\r\nபடைப்பானது அதன் அசல் நிலைக்குப் பிறகு மீண்டும் புதுப்பிக்கப்படுவதை, அதாவது உயிர்த்தெழுதலை மறுப்பவர்களுக்குப் பதிலடி கொடுக்கும் விதமாக அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾ءَأَنتُمْ﴿</span><br />\r\n<br />\r\n(மக்களே! நீங்கள்) <span class=\"quran-arabic-font text-success\">﴾أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">خَلْقًا</span> <span class=\"quran-arabic-font text-success\">أَمِ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءُ﴿</span><br />\r\n<br />\r\n(படைக்கப்படுவதற்கு மிகவும் கடினமானவர்களா? அல்லது வானமா?) அதாவது, \"உங்களை விட வானத்தைப் படைப்பதே மிகவும் கடினமான செயலாகும்.\" இதையே அல்லாஹ் (மற்றொரு வசனத்தில்) கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾لَخَلْقُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْقِ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, வானங்களையும் பூமியையும் படைப்பது மனிதர்களைப் படைப்பதை விடப் பெரியதாகும்.) (<a href=\"qurandisp.php?sura=40&ayah=57\" class=\"link\">40:57</a>). மேலும் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَوَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بِقَادِرٍ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَ</span> <span class=\"quran-arabic-font text-success\">مِثْلَهُم</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">بَلَىٰ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْخَلَّاقُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ﴿</span><br />\r\n<br />\r\n(வானங்களையும் பூமியையும் படைத்தவன், அவர்களைப் போன்றவர்களைப் படைக்க ஆற்றல் பெற்றவன் இல்லையா? ஆம், நிச்சயமாக! அவனே மகா படைப்பாளன், அனைத்தையும் அறிந்தவன்.) (<a href=\"qurandisp.php?sura=36&ayah=81\" class=\"link\">36:81</a>). பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾بَنَاهَا﴿</span><br />\r\n<br />\r\n(அவன் அதனை அமைத்தான்). இதனைத் தொடரும் வசனத்தின் மூலம் அவன் விளக்குகிறான்: <span class=\"quran-arabic-font text-success\">﴾رَفَعَ</span> <span class=\"quran-arabic-font text-success\">سَمْكَهَا</span> <span class=\"quran-arabic-font text-success\">فَسَوَّاهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவன் அதன் முகட்டை உயர்த்தி, அதனைச் சீராக்கினான்.) அதாவது, அவன் அதனை மிக உயர்ந்த கட்டமைப்பாகவும், பரந்த இடத்தைக் கொண்டதாகவும், அனைத்துப் பக்கங்களிலும் சீரானதாகவும் ஆக்கினான். மேலும், இருள் சூழ்ந்த இரவில் அதனை நட்சத்திரங்களைக் கொண்டு அழகுபடுத்தினான்.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَأَغْطَشَ</span> <span class=\"quran-arabic-font text-success\">لَيْلَهَا</span> <span class=\"quran-arabic-font text-success\">وَأَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا﴿</span><br />\r\n<br />\r\n(அதன் இரவை அவன் இருளாக்கி, அதன் முற்பகலை வெளிப்படுத்தினான்.) அதாவது, அவன் அதன் இரவை மிகக் கருமையான இருளாகவும், அதன் பகலைப் பிரகாசமானதாகவும், ஒளிமிக்கதாகவும், தெளிவானதாகவும் ஆக்கினான். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"அவன் அதன் இரவை 'அஃதஷ' (Aghtasha) செய்தான் என்றால், அதனை இருளாக்கினான் என்று பொருள்படும்\" என்றார்கள். முஜாஹித், இக்ரிமா, ஸயீத் பின் ஜுபைர் மற்றும் அறிஞர்கள் பலரும் இவ்வாறே கூறியுள்ளனர். அல்லாஹ்வின் வசனமான <span class=\"quran-arabic-font text-success\">﴾وَأَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا﴿</span><br />\r\n<br />\r\n(மேலும் அவன் அதன் முற்பகலை வெளிப்படுத்தினான்.) என்பது, அவன் அதன் பகலை ஒளிரச் செய்தான் என்பதைக் குறிக்கிறது.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">دَحَاهَا﴿</span><br />\r\n<br />\r\n(இதற்குப் பிறகு அவன் பூமியை விரித்தான்.) இந்த வசனத்தை அதற்கு அடுத்து வரும் வசனமே விளக்குகிறது: <span class=\"quran-arabic-font text-success\">﴾أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">مَاءَهَا</span> <span class=\"quran-arabic-font text-success\">وَمَرْعَاهَا﴿</span><br />\r\n<br />\r\n(அதிலிருந்து அதன் தண்ணீரையும் அதன் மேய்ச்சல் நிலத்தையும் அவன் வெளிப்படுத்தினான்.) வானம் படைக்கப்படுவதற்கு முன்னரே பூமி படைக்கப்பட்டுவிட்டது என்பதும், வானம் படைக்கப்பட்ட பின்னரே பூமி விரித்தமைக்கப்பட்டது என்பதும் ஸூரா 'ஹா மீம் அஸ்-ஸஜ்தா'வில் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது. அதாவது, பூமியில் உள்ளவற்றை அவன் ஒரு வலிமையான செயல்பாட்டின் மூலம் வெளிப்படுத்தினான். இதுவே இப்னு அப்பாஸ் (ரழி) உள்ளிட்டோர் கூறிய கருத்தாகும்; இமாம் இப்னு ஜரீர் அவர்களும் இந்த விளக்கத்தையே தேர்ந்தெடுத்துள்ளார்கள்.<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனமான <span class=\"quran-arabic-font text-success\">﴾وَالْجِبَالَ</span> <span class=\"quran-arabic-font text-success\">أَرْسَاهَا﴿</span><br />\r\n<br />\r\n(மலைகளை அவன் உறுதியாக நிலைநாட்டினான்.) என்பது, அவன் அவற்றை நிலைநிறுத்தி, உறுதியாக்கி, அவற்றுக்குரிய இடங்களில் நிலைபெறச் செய்தான் என்பதைக் குறிக்கிறது. அவன் மகா ஞானமிக்கவன், எல்லாம் அறிந்தவன். அவன் தனது படைப்புகளிடம் மிகுந்த அன்புடையவன், மகா கருணையாளன்.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾مَتَاعًا</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلِأَنْعَامِكُمْ﴿</span><br />\r\n<br />\r\n(உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் பயனளிப்பதற்காக.) அதாவது, அவன் பூமியை விரித்து, அதன் நீரூற்றுகளைப் பீறிடச் செய்து, அதில் மறைந்துள்ள நன்மைகளை வெளிப்படுத்தி, ஆறுகளை ஓடச் செய்தான். மேலும் தாவரங்கள், மரங்கள் மற்றும் கனிகளை வளரச் செய்தான். பூமியில் வசிப்பவர்களுடன் பூமி அமைதியாக நிலைத்திருக்க அதன் மலைகளை அவன் உறுதியாக்கினான்; வசிப்பிடங்களை நிலைப்படுத்தினான். இவை அனைத்தும் அவனது படைப்புகளுக்கு (மனிதர்களுக்கு) பயனளிக்கும் வசதிகளாகும்; அவர்களுக்குத் தேவையான கால்நடைகளையும் அவன் வழங்கினான், அவற்றை அவர்கள் உணவாகக் கொள்கின்றனர், சவாரி செய்யவும் பயன்படுத்துகின்றனர். இந்த உலக வாழ்க்கையில் அவர்களுக்குத் தேவைப்படும் காலம் வரை, அதாவது இம்மை வாழ்வு முடிந்து காலம் முடியும் வரை, இந்த பயனுள்ள அருட்கொடைகளை அவன் அவர்களுக்கு வழங்கியுள்ளான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"படைப்பை மீண்டும் உருவாக்குவதை விட வானங்களையும் பூமியையும் படைப்பது மிகவும் கடினமானது\n\r\n\n\r\nபடைப்பானது அதன் அசல் நிலைக்குப் பிறகு மீண்டும் புதுப்பிக்கப்படுவதை, அதாவது உயிர்த்தெழுதலை மறுப்பவர்களுக்குப் பதிலடி கொடுக்கும் விதமாக அல்லாஹ் கூறுகிறான்: ﴾ءَأَنتُمْ﴿\n\r\n\n\r\n(மக்களே! நீங்கள்) ﴾أَشَدُّ خَلْقًا أَمِ السَّمَاءُ﴿\n\r\n\n\r\n(படைக்கப்படுவதற்கு மிகவும் கடினமானவர்களா? அல்லது வானமா?) அதாவது, \"உங்களை விட வானத்தைப் படைப்பதே மிகவும் கடினமான செயலாகும்.\" இதையே அல்லாஹ் (மற்றொரு வசனத்தில்) கூறுகிறான்: ﴾لَخَلْقُ السَّمَاوَاتِ وَالْأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ﴿\n\r\n\n\r\n(நிச்சயமாக, வானங்களையும் பூமியையும் படைப்பது மனிதர்களைப் படைப்பதை விடப் பெரியதாகும்.) (40:57). மேலும் அவன் கூறுகிறான்: ﴾أَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِقَادِرٍ عَلَىٰ أَن يَخْلُقَ مِثْلَهُم ۚ بَلَىٰ وَهُوَ الْخَلَّاقُ الْعَلِيمُ﴿\n\r\n\n\r\n(வானங்களையும் பூமியையும் படைத்தவன், அவர்களைப் போன்றவர்களைப் படைக்க ஆற்றல் பெற்றவன் இல்லையா? ஆம், நிச்சயமாக! அவனே மகா படைப்பாளன், அனைத்தையும் அறிந்தவன்.) (36:81). பிறகு அல்லாஹ் கூறுகிறான்: ﴾بَنَاهَا﴿\n\r\n\n\r\n(அவன் அதனை அமைத்தான்). இதனைத் தொடரும் வசனத்தின் மூலம் அவன் விளக்குகிறான்: ﴾رَفَعَ سَمْكَهَا فَسَوَّاهَا ﴿\n\r\n\n\r\n(அவன் அதன் முகட்டை உயர்த்தி, அதனைச் சீராக்கினான்.) அதாவது, அவன் அதனை மிக உயர்ந்த கட்டமைப்பாகவும், பரந்த இடத்தைக் கொண்டதாகவும், அனைத்துப் பக்கங்களிலும் சீரானதாகவும் ஆக்கினான். மேலும், இருள் சூழ்ந்த இரவில் அதனை நட்சத்திரங்களைக் கொண்டு அழகுபடுத்தினான்.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَاهَا﴿\n\r\n\n\r\n(அதன் இரவை அவன் இருளாக்கி, அதன் முற்பகலை வெளிப்படுத்தினான்.) அதாவது, அவன் அதன் இரவை மிகக் கருமையான இருளாகவும், அதன் பகலைப் பிரகாசமானதாகவும், ஒளிமிக்கதாகவும், தெளிவானதாகவும் ஆக்கினான். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"அவன் அதன் இரவை 'அஃதஷ' (Aghtasha) செய்தான் என்றால், அதனை இருளாக்கினான் என்று பொருள்படும்\" என்றார்கள். முஜாஹித், இக்ரிமா, ஸயீத் பின் ஜுபைர் மற்றும் அறிஞர்கள் பலரும் இவ்வாறே கூறியுள்ளனர். அல்லாஹ்வின் வசனமான ﴾وَأَخْرَجَ ضُحَاهَا﴿\n\r\n\n\r\n(மேலும் அவன் அதன் முற்பகலை வெளிப்படுத்தினான்.) என்பது, அவன் அதன் பகலை ஒளிரச் செய்தான் என்பதைக் குறிக்கிறது.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾وَالْأَرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴿\n\r\n\n\r\n(இதற்குப் பிறகு அவன் பூமியை விரித்தான்.) இந்த வசனத்தை அதற்கு அடுத்து வரும் வசனமே விளக்குகிறது: ﴾أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا﴿\n\r\n\n\r\n(அதிலிருந்து அதன் தண்ணீரையும் அதன் மேய்ச்சல் நிலத்தையும் அவன் வெளிப்படுத்தினான்.) வானம் படைக்கப்படுவதற்கு முன்னரே பூமி படைக்கப்பட்டுவிட்டது என்பதும், வானம் படைக்கப்பட்ட பின்னரே பூமி விரித்தமைக்கப்பட்டது என்பதும் ஸூரா 'ஹா மீம் அஸ்-ஸஜ்தா'வில் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது. அதாவது, பூமியில் உள்ளவற்றை அவன் ஒரு வலிமையான செயல்பாட்டின் மூலம் வெளிப்படுத்தினான். இதுவே இப்னு அப்பாஸ் (ரழி) உள்ளிட்டோர் கூறிய கருத்தாகும்; இமாம் இப்னு ஜரீர் அவர்களும் இந்த விளக்கத்தையே தேர்ந்தெடுத்துள்ளார்கள்.\n\r\n\n\r\nஅல்லாஹ்வின் வசனமான ﴾وَالْجِبَالَ أَرْسَاهَا﴿\n\r\n\n\r\n(மலைகளை அவன் உறுதியாக நிலைநாட்டினான்.) என்பது, அவன் அவற்றை நிலைநிறுத்தி, உறுதியாக்கி, அவற்றுக்குரிய இடங்களில் நிலைபெறச் செய்தான் என்பதைக் குறிக்கிறது. அவன் மகா ஞானமிக்கவன், எல்லாம் அறிந்தவன். அவன் தனது படைப்புகளிடம் மிகுந்த அன்புடையவன், மகா கருணையாளன்.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾مَتَاعًا لَّكُمْ وَلِأَنْعَامِكُمْ﴿\n\r\n\n\r\n(உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் பயனளிப்பதற்காக.) அதாவது, அவன் பூமியை விரித்து, அதன் நீரூற்றுகளைப் பீறிடச் செய்து, அதில் மறைந்துள்ள நன்மைகளை வெளிப்படுத்தி, ஆறுகளை ஓடச் செய்தான். மேலும் தாவரங்கள், மரங்கள் மற்றும் கனிகளை வளரச் செய்தான். பூமியில் வசிப்பவர்களுடன் பூமி அமைதியாக நிலைத்திருக்க அதன் மலைகளை அவன் உறுதியாக்கினான்; வசிப்பிடங்களை நிலைப்படுத்தினான். இவை அனைத்தும் அவனது படைப்புகளுக்கு (மனிதர்களுக்கு) பயனளிக்கும் வசதிகளாகும்; அவர்களுக்குத் தேவையான கால்நடைகளையும் அவன் வழங்கினான், அவற்றை அவர்கள் உணவாகக் கொள்கின்றனர், சவாரி செய்யவும் பயன்படுத்துகின்றனர். இந்த உலக வாழ்க்கையில் அவர்களுக்குத் தேவைப்படும் காலம் வரை, அதாவது இம்மை வாழ்வு முடிந்து காலம் முடியும் வரை, இந்த பயனுள்ள அருட்கொடைகளை அவன் அவர்களுக்கு வழங்கியுள்ளான்."},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=79&ayah=46\" class=\"link\">79:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 79:46 ஐ பார்க்கவும்"},"46":{"html":"<strong>மறுமை நாள், அதன் இன்பங்கள் மற்றும் நரகம், அதன் நேரம் அறியப்படாதது என்பது பற்றியும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَتِ</span> <span class=\"quran-arabic-font text-success\">الطَّآمَّةُ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span><br />\r\n<br />\r\n(மிகப்பெரிய அந்தப் பேரழிவு வரும்போது,) இது மறுமை நாளைக் குறிக்கிறது என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியுள்ளார்கள். இது ஒவ்வொரு விஷயத்தையும் மிகைத்து விடுவதால் இப்பெயர் பெற்றது. இது அச்சமூட்டுவதாகவும் திகிலூட்டுவதாகவும் இருக்கும். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">أَدْهَى</span> <span class=\"quran-arabic-font text-success\">وَأَمَرُّ</span><br />\r\n<br />\r\n(மேலும் அந்த (மறுமை) நேரம் மிகக் கடுமையானதும், மிகக் கசப்பானதுமாகும்.) (<a href=\"qurandisp.php?sura=54&ayah=46\" class=\"link\">54:46</a>) பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَعَى</span><br />\r\n<br />\r\n(மனிதன் தான் செய்த முயற்சியையெல்லாம் நினைவுகூரும் நாள்.) அதாவது, அந்த நேரத்தில் ஆதமின் மகன் தனது நன்மை மற்றும் தீமை என தனது அனைத்துச் செயல்களையும் சிந்தித்துப் பார்ப்பான். இது அல்லாஹ் கூறுவது போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span><br />\r\n<br />\r\n(அந்நாளில் மனிதன் நினைவுகூர்வான்; ஆனால் அந்த நினைவு அவனுக்கு எவ்வாறு பயனளிக்கும்?) (<a href=\"qurandisp.php?sura=89&ayah=23\" class=\"link\">89:23</a>) பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَبُرِّزَتِ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمُ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَرَى</span><br />\r\n<br />\r\n(மேலும் பார்ப்பவருக்கு நரகம் வெளிப்படுத்தப்படும்.) அதாவது, பார்ப்பவர்களுக்கு அது தெளிவாகத் தெரியும், மக்கள் அதனைத் தங்கள் கண்களால் காண்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">طَغَى</span><br />\r\n<br />\r\n(எவன் வரம்பு மீறினானோ,) அதாவது, எவன் மாறுசெய்து கர்வத்துடன் நடந்துகொள்கிறானோ.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءاثَرَ</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(மேலும் இவ்வுலக வாழ்க்கையைத் தேர்ந்தெடுத்தானோ,) அதாவது, தனது மார்க்கம் மற்றும் மறுமை விவகாரங்களை விட உலக வாழ்க்கைக்கு முன்னுரிமை அளிக்கிறானோ.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمَ</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">الْمَأْوَى</span><br />\r\n<br />\r\n(நிச்சயமாக அவனது தங்குமிடம் நரகமே ஆகும்.) அதாவது, அவனது இறுதிச் சேருமிடம் நரகமாகும். அவனது உணவு 'ஜக்கூம்' மரத்திலிருந்தும், அவனது பானம் 'ஹமீம்' (கொதிக்கும் நீர்) இருந்தும் இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">خَافَ</span> <span class=\"quran-arabic-font text-success\">مَقَامَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">وَنَهَى</span> <span class=\"quran-arabic-font text-success\">النَّفْسَ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْهَوَى</span><br />\r\n<br />\r\n(எவன் தன் இறைவனின் முன் நிற்பதை அஞ்சி, தனது மனதை இச்சைகளிலிருந்து தடுத்துக்கொண்டானோ,) அதாவது, அவன் அல்லாஹ்வின் முன்னிலையில் நிற்பதற்கும், அவன் வழங்கப்போகும் தீர்ப்புக்கும் அஞ்சி, தனது ஆத்மா அதன் இச்சைகளைப் பின்பற்றுவதைத் தடுத்து, தன் எஜமானுக்குக் கீழ்ப்படியும்படி செய்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">الْمَأْوَى</span><br />\r\n<br />\r\n(நிச்சயமாக சொர்க்கமே அவனது தங்குமிடமாகும்.) அதாவது, அவனது இறுதி உறைவிடம், சேருமிடம் மற்றும் அவன் திரும்பிச் செல்லும் இடம் விசாலமான சொர்க்கமாக இருக்கும். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَسْأَلُونَكَ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">أَيَّانَ</span> <span class=\"quran-arabic-font text-success\">مُرْسَاهَا</span> - <span class=\"quran-arabic-font text-success\">فِيمَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذِكْرَاهَا</span> - <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">مُنتَهَاهَا</span><br />\r\n<br />\r\n(மறுமை நேரம் எப்பொழுது நிகழும் என்று அவர்கள் உம்மிடம் கேட்கிறார்கள். அதைப் பற்றிச் சொல்வதற்கு உமக்கு என்ன இருக்கிறது? அதன் இறுதி முடிவு உம் இறைவனிடமே உள்ளது.) அதாவது, அதைப் பற்றிய அறிவு உம்மிடமோ அல்லது வேறு எந்தப் படைப்பிடமோ இல்லை. மாறாக, அதன் அறிவு அல்லாஹ்விடம் மட்டுமே உள்ளது. அது நிகழும் சரியான நேரத்தை அறிந்தவன் அவன் ஒருவனே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثَقُلَتْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَأْتِيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً</span> <span class=\"quran-arabic-font text-success\">يَسْأَلُونَكَ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّكَ</span> <span class=\"quran-arabic-font text-success\">حَفِيٌّ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">عِلْمُهَا</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(வானங்களிலும் பூமியிலும் அதன் சுமை கனமாக இருக்கிறது. அது உங்களிடம் திடீரென்று தவிர வராது. நீர் அதனை நன்கு அறிந்தவர் என்பது போல் அவர்கள் உம்மிடம் கேட்கிறார்கள். கூறுவீராக: \"நிச்சயமாக அதன் அறிவு அல்லாஹ்விடமே உள்ளது.\") (<a href=\"qurandisp.php?sura=7&ayah=187\" class=\"link\">7:187</a>) இங்கே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">مُنتَهَاهَا</span><br />\r\n<br />\r\n(அதன் இறுதி முடிவு உம் இறைவனிடமே உள்ளது.) இவ்வாறே, ஜிப்ரீல் (அலை) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் இறுதி நேரம் பற்றி வினவியபோது, அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">الْمَسْؤُولُ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">بِأَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّائِل</span>»<br />\r\n<br />\r\n(கேள்வி கேட்கப்பட்டவர், கேள்வி கேட்பவரை விட அதனைப் பற்றி அதிகம் அறிந்தவர் அல்லர்.) அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مُنذِرُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَخْشَـهَا</span><br />\r\n<br />\r\n(அதற்கு அஞ்சுபவர்களுக்கு நீர் ஒரு எச்சரிக்கையாளர் மட்டுமே.) அதாவது, 'மக்களுக்கு எச்சரிக்கை செய்வதற்காகவும், அல்லாஹ்வின் வேதனை மற்றும் தண்டனை குறித்து விழிப்புடன் இருக்கும்படி செய்வதற்காகவும் நான் உம்மை அனுப்பினேன். எனவே, எவர் அல்லாஹ்வுக்கு அஞ்சி, அவனது முன்னிலையில் நிற்பதற்கும் அவனது எச்சரிக்கைக்கும் பயப்படுகிறாரோ, அவர் உம்மைப் பின்பற்றுவார்; அதன் மூலம் வெற்றியும் ஈடேற்றமும் அடைவார். ஆனால், எவர் உம்மைப் பொய்ப்பித்து உம்மை எதிர்க்கிறாரோ, அவர் நஷ்டத்தையும் தோல்வியையும் அடைவார்.' பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَهَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَلْبَثُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَشِيَّةً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا</span><br />\r\n<br />\r\n(அவர்கள் அதனைக் காணும் நாளில், ஒரு மாலைப் பொழுதோ அல்லது ஒரு காலைப் பொழுதோ தவிர (இவ்வுலகில்) அவர்கள் தங்கியிருக்கவில்லை என்பது போன்றிருக்கும்.) அதாவது, அவர்கள் தங்கள் அடக்கத்தலங்களிலிருந்து எழுப்பப்பட்டு ஒன்று திரட்டப்படும் இடத்திற்குச் செல்லும்போது, இவ்வுலக வாழ்க்கை மிகக் குறுகிய காலமாக இருந்ததை உணர்வார்கள். அது அவர்களுக்கு ஒரு நாளின் பிற்பகல் பொழுது மட்டுமே என்பது போல் தோன்றும். ஜுவைபிர் அவர்கள் அழ்-ளஹ்ஹாக் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَهَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَلْبَثُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَشِيَّةً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا</span><br />\r\n<br />\r\n(அவர்கள் அதனைக் காணும் நாளில், ஒரு மாலைப் பொழுதோ அல்லது ஒரு காலைப் பொழுதோ தவிர (இவ்வுலகில்) அவர்கள் தங்கியிருக்கவில்லை என்பது போன்றிருக்கும்.) \"'அஷிய்யா' என்பது நண்பகல் முதல் சூரியன் மறையும் வரையிலான நேரமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا</span><br />\r\n<br />\r\n(அல்லது அதன் காலைப்பொழுது) என்பது சூரிய உதயம் முதல் நண்பகல் வரையிலான நேரமாகும்.\" கத்தாதா அவர்கள் கூறினார்கள்: \"மக்கள் மறுமையைக் காணும்போது, அவர்களின் பார்வையில் இவ்வுலக வாழ்க்கையின் கால அளவு இவ்வாறுதான் இருக்கும்.\" இதுவே சூரத் அந்-நாஸிஆத்தின் தஃப்ஸீரின் முடிவாகும். அனைத்துப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மறுமை நாள், அதன் இன்பங்கள் மற்றும் நரகம், அதன் நேரம் அறியப்படாதது என்பது பற்றியும்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَإِذَا جَآءَتِ الطَّآمَّةُ الْكُبْرَى\n\r\n\n\r\n(மிகப்பெரிய அந்தப் பேரழிவு வரும்போது,) இது மறுமை நாளைக் குறிக்கிறது என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியுள்ளார்கள். இது ஒவ்வொரு விஷயத்தையும் மிகைத்து விடுவதால் இப்பெயர் பெற்றது. இது அச்சமூட்டுவதாகவும் திகிலூட்டுவதாகவும் இருக்கும். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَالسَّاعَةُ أَدْهَى وَأَمَرُّ\n\r\n\n\r\n(மேலும் அந்த (மறுமை) நேரம் மிகக் கடுமையானதும், மிகக் கசப்பானதுமாகும்.) (54:46) பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَوْمَ يَتَذَكَّرُ الإِنسَـنُ مَا سَعَى\n\r\n\n\r\n(மனிதன் தான் செய்த முயற்சியையெல்லாம் நினைவுகூரும் நாள்.) அதாவது, அந்த நேரத்தில் ஆதமின் மகன் தனது நன்மை மற்றும் தீமை என தனது அனைத்துச் செயல்களையும் சிந்தித்துப் பார்ப்பான். இது அல்லாஹ் கூறுவது போன்றது:\n\r\n\n\r\nيَوْمَئِذٍ يَتَذَكَّرُ الإِنسَـنُ وَأَنَّى لَهُ الذِّكْرَى\n\r\n\n\r\n(அந்நாளில் மனிதன் நினைவுகூர்வான்; ஆனால் அந்த நினைவு அவனுக்கு எவ்வாறு பயனளிக்கும்?) (89:23) பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَبُرِّزَتِ الْجَحِيمُ لِمَن يَرَى\n\r\n\n\r\n(மேலும் பார்ப்பவருக்கு நரகம் வெளிப்படுத்தப்படும்.) அதாவது, பார்ப்பவர்களுக்கு அது தெளிவாகத் தெரியும், மக்கள் அதனைத் தங்கள் கண்களால் காண்பார்கள்.\n\r\n\n\r\nفَأَمَّا مَن طَغَى\n\r\n\n\r\n(எவன் வரம்பு மீறினானோ,) அதாவது, எவன் மாறுசெய்து கர்வத்துடன் நடந்துகொள்கிறானோ.\n\r\n\n\r\nوَءاثَرَ الْحَيَوةَ الدُّنْيَا\n\r\n\n\r\n(மேலும் இவ்வுலக வாழ்க்கையைத் தேர்ந்தெடுத்தானோ,) அதாவது, தனது மார்க்கம் மற்றும் மறுமை விவகாரங்களை விட உலக வாழ்க்கைக்கு முன்னுரிமை அளிக்கிறானோ.\n\r\n\n\r\nفَإِنَّ الْجَحِيمَ هِىَ الْمَأْوَى\n\r\n\n\r\n(நிச்சயமாக அவனது தங்குமிடம் நரகமே ஆகும்.) அதாவது, அவனது இறுதிச் சேருமிடம் நரகமாகும். அவனது உணவு 'ஜக்கூம்' மரத்திலிருந்தும், அவனது பானம் 'ஹமீம்' (கொதிக்கும் நீர்) இருந்தும் இருக்கும்.\n\r\n\n\r\nوَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى\n\r\n\n\r\n(எவன் தன் இறைவனின் முன் நிற்பதை அஞ்சி, தனது மனதை இச்சைகளிலிருந்து தடுத்துக்கொண்டானோ,) அதாவது, அவன் அல்லாஹ்வின் முன்னிலையில் நிற்பதற்கும், அவன் வழங்கப்போகும் தீர்ப்புக்கும் அஞ்சி, தனது ஆத்மா அதன் இச்சைகளைப் பின்பற்றுவதைத் தடுத்து, தன் எஜமானுக்குக் கீழ்ப்படியும்படி செய்கிறான்.\n\r\n\n\r\nفَإِنَّ الْجَنَّةَ هِىَ الْمَأْوَى\n\r\n\n\r\n(நிச்சயமாக சொர்க்கமே அவனது தங்குமிடமாகும்.) அதாவது, அவனது இறுதி உறைவிடம், சேருமிடம் மற்றும் அவன் திரும்பிச் செல்லும் இடம் விசாலமான சொர்க்கமாக இருக்கும். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا - فِيمَ أَنتَ مِن ذِكْرَاهَا - إِلَى رَبِّكَ مُنتَهَاهَا\n\r\n\n\r\n(மறுமை நேரம் எப்பொழுது நிகழும் என்று அவர்கள் உம்மிடம் கேட்கிறார்கள். அதைப் பற்றிச் சொல்வதற்கு உமக்கு என்ன இருக்கிறது? அதன் இறுதி முடிவு உம் இறைவனிடமே உள்ளது.) அதாவது, அதைப் பற்றிய அறிவு உம்மிடமோ அல்லது வேறு எந்தப் படைப்பிடமோ இல்லை. மாறாக, அதன் அறிவு அல்லாஹ்விடம் மட்டுமே உள்ளது. அது நிகழும் சரியான நேரத்தை அறிந்தவன் அவன் ஒருவனே.\n\r\n\n\r\nثَقُلَتْ فِي السَّمَاوَاتِ وَالْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْأَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ اللَّهِ\n\r\n\n\r\n(வானங்களிலும் பூமியிலும் அதன் சுமை கனமாக இருக்கிறது. அது உங்களிடம் திடீரென்று தவிர வராது. நீர் அதனை நன்கு அறிந்தவர் என்பது போல் அவர்கள் உம்மிடம் கேட்கிறார்கள். கூறுவீராக: \"நிச்சயமாக அதன் அறிவு அல்லாஹ்விடமே உள்ளது.\") (7:187) இங்கே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِلَى رَبِّكَ مُنتَهَاهَا\n\r\n\n\r\n(அதன் இறுதி முடிவு உம் இறைவனிடமே உள்ளது.) இவ்வாறே, ஜிப்ரீல் (அலை) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் இறுதி நேரம் பற்றி வினவியபோது, அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا الْمَسْؤُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِل»\n\r\n\n\r\n(கேள்வி கேட்கப்பட்டவர், கேள்வி கேட்பவரை விட அதனைப் பற்றி அதிகம் அறிந்தவர் அல்லர்.) அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَـهَا\n\r\n\n\r\n(அதற்கு அஞ்சுபவர்களுக்கு நீர் ஒரு எச்சரிக்கையாளர் மட்டுமே.) அதாவது, 'மக்களுக்கு எச்சரிக்கை செய்வதற்காகவும், அல்லாஹ்வின் வேதனை மற்றும் தண்டனை குறித்து விழிப்புடன் இருக்கும்படி செய்வதற்காகவும் நான் உம்மை அனுப்பினேன். எனவே, எவர் அல்லாஹ்வுக்கு அஞ்சி, அவனது முன்னிலையில் நிற்பதற்கும் அவனது எச்சரிக்கைக்கும் பயப்படுகிறாரோ, அவர் உம்மைப் பின்பற்றுவார்; அதன் மூலம் வெற்றியும் ஈடேற்றமும் அடைவார். ஆனால், எவர் உம்மைப் பொய்ப்பித்து உம்மை எதிர்க்கிறாரோ, அவர் நஷ்டத்தையும் தோல்வியையும் அடைவார்.' பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُواْ إِلاَّ عَشِيَّةً أَوْ ضُحَاهَا\n\r\n\n\r\n(அவர்கள் அதனைக் காணும் நாளில், ஒரு மாலைப் பொழுதோ அல்லது ஒரு காலைப் பொழுதோ தவிர (இவ்வுலகில்) அவர்கள் தங்கியிருக்கவில்லை என்பது போன்றிருக்கும்.) அதாவது, அவர்கள் தங்கள் அடக்கத்தலங்களிலிருந்து எழுப்பப்பட்டு ஒன்று திரட்டப்படும் இடத்திற்குச் செல்லும்போது, இவ்வுலக வாழ்க்கை மிகக் குறுகிய காலமாக இருந்ததை உணர்வார்கள். அது அவர்களுக்கு ஒரு நாளின் பிற்பகல் பொழுது மட்டுமே என்பது போல் தோன்றும். ஜுவைபிர் அவர்கள் அழ்-ளஹ்ஹாக் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nكَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُواْ إِلاَّ عَشِيَّةً أَوْ ضُحَاهَا\n\r\n\n\r\n(அவர்கள் அதனைக் காணும் நாளில், ஒரு மாலைப் பொழுதோ அல்லது ஒரு காலைப் பொழுதோ தவிர (இவ்வுலகில்) அவர்கள் தங்கியிருக்கவில்லை என்பது போன்றிருக்கும்.) \"'அஷிய்யா' என்பது நண்பகல் முதல் சூரியன் மறையும் வரையிலான நேரமாகும்.\n\r\n\n\r\nأَوْ ضُحَاهَا\n\r\n\n\r\n(அல்லது அதன் காலைப்பொழுது) என்பது சூரிய உதயம் முதல் நண்பகல் வரையிலான நேரமாகும்.\" கத்தாதா அவர்கள் கூறினார்கள்: \"மக்கள் மறுமையைக் காணும்போது, அவர்களின் பார்வையில் இவ்வுலக வாழ்க்கையின் கால அளவு இவ்வாறுதான் இருக்கும்.\" இதுவே சூரத் அந்-நாஸிஆத்தின் தஃப்ஸீரின் முடிவாகும். அனைத்துப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
